import { Injectable } from '@angular/core';
import { CaseUserInfoReq, TimeZoneRes, UserBuilderReq, UserBuilderRes, UserDeleteReq, UserDeleteRes, UserProfileUpload, roleComboResponce, teamComboResponce, teamDeleteReq, teamDeleteRes, userListResponce } from '../../interfaces/teamsetup.interface';
import { firstValueFrom } from 'rxjs';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { HttpClient, HttpParams } from '@angular/common/http';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { environment } from '../../../../environments/environment';
import { UserDetail } from '../../../core/interfaces/login.interface';

@Injectable({
  providedIn: 'root'
})
export class UserService {

  constructor(public sStore: SecureStorageService, private http: HttpClient, public tost: TostbarService) { }



  async userBuilder(mdl: UserBuilderReq): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<UserBuilderRes>(`${environment.cloudUrl}${environment.coreservice}/team-setup/userbuilder`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`User creation failed ${err}`, 'E');
      return false;
    }
  }


  async teamDelete(mdl: teamDeleteReq): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<teamDeleteRes>(`${environment.cloudUrl}${environment.coreservice}/team-setup/teamdelete`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`team deletion failed ${err}`, 'E');
      return false;
    }
  }

  async userDetail(mdl: CaseUserInfoReq): Promise<boolean> {
    try {
      var params = new HttpParams()
      for (const key in mdl) {
        if (mdl.hasOwnProperty(key)) {
          params = params.set(key, mdl[key]);
        }
      }
      const res: any = await firstValueFrom(
        this.http.get<userListResponce[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/getuserdetail`,
          { params: params }
        )
      );

      return (res && res.length > 0) ? res[0] : null;
    } catch (err) {
      // this.tost.openSnackBar(`User creation failed ${err}`, 'E');
      return false;
    }
  }

  async teamCombo(nCaseid: string): Promise<teamComboResponce[]> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<teamComboResponce[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/teamcombo`,
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return [];
    }
  }


  async roleCombo(): Promise<roleComboResponce[]> {
    try {
      const res: any = await firstValueFrom(
        this.http.get<roleComboResponce[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/rolelist`
        )
      );

      return res;
    } catch (err) {
      return [];
    }
  }



  async timezoneCombo(): Promise<TimeZoneRes[]> {
    try {
      const res: any = await firstValueFrom(
        this.http.get<TimeZoneRes[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/timezone`
        )
      );

      return res;
    } catch (err) {
      return [];
    }
  }


  async userDelete(mdl: UserDeleteReq): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<UserDeleteRes>(`${environment.cloudUrl}${environment.coreservice}/team-setup/userdelete`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`User deletion failed ${err}`, 'E');
      return false;
    }
  }

  async checkEmailexists(cEmail: string, nCaseid: string): Promise<UserDetail> {
    var params = new HttpParams().set('cEmail', cEmail);
    params = params.set('nCaseid', nCaseid);
    try {
      const res: UserDetail = await firstValueFrom(
        this.http.get<UserDetail>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/checkemail`,
          { params: params }
        )
      );
      return res;
    } catch (err) {
      console.error(err);
      this.tost.openSnackBar(`User Fatching failed`, 'E');
      return {};
    }
  }

  async userProfileUpload(mdl: FormData): Promise<UserProfileUpload> {
    try {
      const res = await firstValueFrom(
        this.http.post<any>(
          `${environment.uploadservice}/profile/upload-image`, mdl)
      );
      if (res.msg == -1) {
        this.tost.openSnackBar(`Profile Upload failed ${res.error}`, 'E');
        return { msg: -1, error: res.error, value: '' };
      }
      else {
        return res;
      }
    } catch (err: any) {
      this.tost.openSnackBar(`Profile Upload failed ${err}`, 'E');
      return { msg: -1, error: err, value: '' };
    }
  }

}
